package com.mendes.scheduling_platform.subscription; import com.mendes.scheduling_platform.exception.NotFoundException; import com.mendes.scheduling_platform.security.TenantContext; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/subscription") public class SubscriptionController {private final SubscriptionRepository repo;public SubscriptionController(SubscriptionRepository r){repo=r;}@GetMapping Subscription current(){return repo.findByTenantId(TenantContext.getRequired()).orElseThrow(()->new NotFoundException("Assinatura não encontrada"));}}
